module tb_TopModule;
    logic        clk;
    logic        reset;
    logic [9:0]  q;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        #12;
        @(posedge clk);
        if (q !== 10'd0) begin
            $display("SELFTEST FAIL: Reset failed, q=%d", q);
            $finish;
        end

        reset = 0;

        // Check first few cycles
        @(posedge clk); #1;
        if (q !== 10'd1) begin $display("SELFTEST FAIL: at q=%d (expected 1)", q); $finish; end
        @(posedge clk); #1;
        if (q !== 10'd2) begin $display("SELFTEST FAIL: at q=%d (expected 2)", q); $finish; end

        // Fast forward to near 999
        // We can wait until q == 999
        while (q !== 10'd999) begin
            @(posedge clk);
        end
        #1;
        if (q !== 10'd999) begin $display("SELFTEST FAIL: failed to reach 999"); $finish; end

        // Next cycle should be 0
        @(posedge clk); #1;
        if (q !== 10'd0) begin $display("SELFTEST FAIL: wrap around failed, q=%d", q); $finish; end

        // Next cycle should be 1
        @(posedge clk); #1;
        if (q !== 10'd1) begin $display("SELFTEST FAIL: post-wrap failed, q=%d", q); $finish; end

        // Test synchronous reset in the middle
        reset = 1;
        @(posedge clk); #1;
        if (q !== 10'd0) begin $display("SELFTEST FAIL: mid-count reset failed, q=%d", q); $finish; end
        reset = 0;

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

