module tb_TopModule;
    logic        clk;
    logic        reset;
    logic [9:0]  q;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        @(posedge clk);
        @(posedge clk);
        #1;
        if (q !== 10'd0) begin
            $display("SELFTEST FAIL: Reset failed, q=%d", q);
            $finish;
        end

        reset = 0;

        @(posedge clk); #1;
        if (q !== 10'd1) begin $display("SELFTEST FAIL: at q=%d (expected 1)", q); $finish; end

        @(posedge clk); #1;
        if (q !== 10'd2) begin $display("SELFTEST FAIL: at q=%d (expected 2)", q); $finish; end

        // Test fast forward or wait until 999
        // 999 cycles is a bit long for explicit @(posedge clk) one by one in code, but in simulation it's instant.
        // Let's loop.
        for (int i = 2; i < 999; i++) begin
            @(posedge clk);
        end
        #1;
        if (q !== 10'd999) begin
            $display("SELFTEST FAIL: Expected 999, got %d", q);
            $finish;
        end

        // Next clock should wrap to 0
        @(posedge clk); #1;
        if (q !== 10'd0) begin
            $display("SELFTEST FAIL: Wrap around failed, got %d", q);
            $finish;
        end

        // Next clock should be 1
        @(posedge clk); #1;
        if (q !== 10'd1) begin
            $display("SELFTEST FAIL: Post-wrap failed, got %d", q);
            $finish;
        end

        // Test synchronous reset
        reset = 1;
        @(posedge clk); #1;
        if (q !== 10'd0) begin
            $display("SELFTEST FAIL: Sync reset failed, got %d", q);
            $finish;
        end

        reset = 0;
        @(posedge clk); #1;
        if (q !== 10'd1) begin
            $display("SELFTEST FAIL: Post-reset count failed, got %d", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
